// Upstream availability as observed by this node during the last scan.
type SourceStatusObjStatus string

const (
	SourceStatusObjStatusAvailable     SourceStatusObjStatus = "available"
	SourceStatusObjStatusTemporaryDown SourceStatusObjStatus = "temporary_down"
	SourceStatusObjStatusPermanentDown SourceStatusObjStatus = "permanent_down"
	SourceStatusObjStatusUnknown       SourceStatusObjStatus = "unknown"
)

// AllValues returns all SourceStatusObjStatus values.
func (SourceStatusObjStatus) AllValues() []SourceStatusObjStatus {
	return []SourceStatusObjStatus{
		SourceStatusObjStatusAvailable,
		SourceStatusObjStatusTemporaryDown,
		SourceStatusObjStatusPermanentDown,
		SourceStatusObjStatusUnknown,
	}
}

// MarshalText implements encoding.TextMarshaler.
func (s SourceStatusObjStatus) MarshalText() ([]byte, error) {
	switch s {
	case SourceStatusObjStatusAvailable:
		return []byte(s), nil
	case SourceStatusObjStatusTemporaryDown:
		return []byte(s), nil
	case SourceStatusObjStatusPermanentDown:
		return []byte(s), nil
	case SourceStatusObjStatusUnknown:
		return []byte(s), nil
	default:
		return nil, errors.Errorf("invalid value: %q", s)
	}
}

// UnmarshalText implements encoding.TextUnmarshaler.
func (s *SourceStatusObjStatus) UnmarshalText(data []byte) error {
	switch SourceStatusObjStatus(data) {
	case SourceStatusObjStatusAvailable:
		*s = SourceStatusObjStatusAvailable
		return nil
	case SourceStatusObjStatusTemporaryDown:
		*s = SourceStatusObjStatusTemporaryDown
		return nil
	case SourceStatusObjStatusPermanentDown:
		*s = SourceStatusObjStatusPermanentDown
		return nil
	case SourceStatusObjStatusUnknown:
		*s = SourceStatusObjStatusUnknown
		return nil
	default:
		return errors.Errorf("invalid value: %q", data)
	}
}
